contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: depositor address is this contract; amount is the ETH value to send
    // The test attempts a Deposit of amount 'amt' and then asserts balances[this]==old+amt
    function run(uint amt) public payable {
        // we need this contract to hold at least amt wei to forward
        require(address(this).balance >= amt, "insufficient test balance");

        // read prior balance of this contract in C
        uint before = c.balances(address(this));

        // call Deposit on c with ETH value amt
        c.Deposit{value: amt}();

        // read after balance
        uint after = c.balances(address(this));

        // The distinguishing rule: if amt equals MinDeposit then deposit is accepted
        // so after == before + amt when amt == c.MinDeposit()
        assert(!(amt == c.MinDeposit()) || (after == before + amt));
    }

    receive() external payable {}
}

