        // read MinDeposit via its public getter
        uint min = c.MinDeposit();
        require(amount == min);
        // perform the deposit
        c.Deposit{value: amount}();
        // After depositing exactly MinDeposit, the caller's recorded balance should have increased by amount
        // c.balances is a public mapping getter
        assert(c.balances(address(this)) == amount);
    }
    receive() external payable {}
}

