pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // Fuzz params: depositor, other account, depositAmount, cashoutAmount
    function testFuzz_property(address depositor, address other, uint256 depositAmount, uint256 cashoutAmount) public {
        // Keep addresses distinct to observe effect on "other"
        vm.assume(depositor != address(0));
        vm.assume(other != address(0));
        vm.assume(depositor != other);

        // Bound depositAmount and cashoutAmount to reasonable ranges and ensure deposit meets MinDeposit
        uint256 min = 1 ether;
        uint256 dep = bound(depositAmount, min, 10 ether);
        uint256 co   = bound(cashoutAmount, 0, 10 ether);

        // Give funds to depositor and other so they can interact if needed
        vm.deal(depositor, dep + 1 ether);
        vm.deal(other, 1 ether);

        // Record other's initial recorded balance (should be 0 initially)
        uint256 other_before = c.balances(other);

        // Perform a deposit from depositor
        vm.prank(depositor);
        c.Deposit{value: dep}();

        // Now attempt to cash out 'co' from depositor (only valid effect if co <= recorded balance)
        bool ok;
        try c.CashOut(co) {
            ok = true;
        } catch {
            ok = false;
        }

        // After CashOut completes, the reference contract guarantees that other account's recorded balance
        // has not decreased unexpectedly (i.e., remains >= previous value). We read the public getter.
        uint256 other_after = c.balances(other);

        // Single assertion: in the correct contract for all inputs other_after >= other_before holds.
        // The mutant that overwrites balances on Deposit can cause other_after < other_before for some inputs,
        // so the fuzzer will find such inputs and make this assert fail on the mutant.
        assertTrue(other_after >= other_before);
    }
}

