pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this)); }

    // fuzz parameters: depositor, other account, deposit amount, withdraw amount
    function testFuzz_property(address depositor, address other, uint256 depositAmt, uint256 withdrawAmt) public {
        // keep addresses non-zero and distinct to avoid trivialities
        vm.assume(depositor != address(0));
        vm.assume(other != address(0));
        vm.assume(depositor != other);

        // bound depositAmt to a reasonable range and ensure it's at least MinDeposit
        uint256 min = 1 ether;
        depositAmt = bound(depositAmt, min, 10 ether);
        // bound withdrawAmt
        withdrawAmt = bound(withdrawAmt, 0, 10 ether);

        // Fund depositor and other so deposits and potential withdrawals can proceed
        vm.deal(depositor, depositAmt + 1 ether);
        vm.deal(other, 1 ether);

        // depositor makes an initial Deposit
        vm.prank(depositor);
        c.Deposit{value: depositAmt}();

        // Record other's stored balance before any withdrawal
        uint256 otherBefore = c.balances(other);

        // Ensure withdrawAmt is not greater than depositor's recorded balance to allow CashOut path
        // If withdrawAmt > balances[depositor], CashOut will do nothing; keep admissible domain wide
        uint256 depositorBalance = c.balances(depositor);
        // bound withdrawAmt to [0, depositorBalance]
        if (depositorBalance == 0) {
            withdrawAmt = 0;
        } else {
            withdrawAmt = withdrawAmt % (depositorBalance + 1);
        }

        // Make depositor attempt to CashOut withdrawAmt
        bool ok;
        vm.prank(depositor);
        try c.CashOut(withdrawAmt) {
            ok = true;
        } catch {
            ok = false;
        }

        // General invariant: in the reference implementation, other account's stored balance never changes
        // as a result of someone else's CashOut; assert that observed stored balance equals prior value.
        uint256 otherAfter = c.balances(other);
        assertTrue(otherAfter == otherBefore);
    }
}

