pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this)); }

    // Fuzz parameters: depositor, otherAccount, depositAmount, withdrawAmount
    function testFuzz_property(address depositor, address otherAccount, uint256 depositAmount, uint256 withdrawAmount) public {
        // Keep addresses non-zero and distinct to avoid trivial collisions
        vm.assume(depositor != address(0));
        vm.assume(otherAccount != address(0));
        // allow same as depositor as well (property still should hold), but keep wide

        // bound amounts to reasonable ranges; MinDeposit is 1 ether
        depositAmount = bound(depositAmount, 1 wei, 10 ether);
        withdrawAmount = bound(withdrawAmount, 0, type(uint256).max);

        // Ensure deposit meets MinDeposit to be recorded
        if (depositAmount < 1 ether) depositAmount = 1 ether;

        // Fund accounts
        vm.deal(depositor, depositAmount + 1 ether);
        vm.deal(otherAccount, 1 ether);

        // otherAccount makes some deposit as well to create non-zero stored value
        vm.startPrank(otherAccount);
        c.Deposit{value: 1 ether}();
        vm.stopPrank();

        // Record otherAccount's balance before depositor activity
        uint beforeOther = c.balances(otherAccount);

        // depositor makes deposit
        vm.startPrank(depositor);
        c.Deposit{value: depositAmount}();

        // bound withdrawAmount to at most depositor's recorded balance to exercise successful CashOut path
        uint recorded = c.balances(depositor);
        if (recorded == 0) {
            // nothing to withdraw; end test by asserting otherAccount unchanged
            vm.stopPrank();
            assertTrue(c.balances(otherAccount) == beforeOther);
            return;
        }
        uint w = withdrawAmount % (recorded + 1); // 0..recorded

        // Call CashOut; we observe no revert (since w <= recorded)
        try c.CashOut(w) {
            // ok
        } catch {
            // If it reverts unexpectedly, still check other balance unchanged (reference should not revert here)
            vm.stopPrank();
            assertTrue(c.balances(otherAccount) == beforeOther);
            return;
        }
        vm.stopPrank();

        // Single assertion: otherAccount's stored balance must remain equal to beforeOther
        assertTrue(c.balances(otherAccount) == beforeOther);
    }
}

