pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this)); }

    // Fuzz parameters: depositor address and two deposit amounts
    function testFuzz_property(address depositor, uint256 firstDeposit, uint256 secondDeposit) public {
        // Keep amounts in a wide admissible domain but respect MinDeposit (1 ether)
        uint256 min = 1 ether;
        // bound deposits to reasonable range so vm.deal won't overflow and to keep test meaningful
        firstDeposit = bound(firstDeposit, min, 1e24); // up to 1 million ether
        secondDeposit = bound(secondDeposit, min, 1e24);
        // disallow zero-address depositor because vm.prank with address(0) is ambiguous
        vm.assume(depositor != address(0));

        // Provide Ether to depositor so they can deposit twice
        vm.deal(depositor, firstDeposit + secondDeposit + 1 ether);

        // First deposit
        vm.prank(depositor);
        c.Deposit{value: firstDeposit}();
        uint256 afterFirst = c.balances(depositor);

        // Second deposit
        vm.prank(depositor);
        c.Deposit{value: secondDeposit}();
        uint256 afterSecond = c.balances(depositor);

        // The general invariant for the correct contract C:
        // after two deposits by the same depositor, the recorded balance equals the sum of the two deposits
        // (i.e., additive behavior: balances = prior + first + second). We assert that here.
        assertTrue(afterSecond == afterFirst + secondDeposit);
    }
}
